T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "Все: никогда не стоять перед Ониксией или позади неё (дыхание/хвост).\nФаза 2 с 65%: уклоняться от огненных шаров, щенков убивать сразу.\nФаза 3 с 40%: страх - тотем заземления и защита от страха наготове.\nТанк: Ониксия спиной к стене, голова от рейда.\nТанк: в фазе 3 сразу вернуть агро.\nЛекари: танк в приоритете, в фазе 2 стоять рассредоточенно.\nБойцы: в полную силу только после 3 раскалываний брони от танка.\nБойцы: фаза 2: щенки важнее Ониксии."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "Все: цель роя - выбегай.\nТанк: танк инферналов в стороне.\nЛекари: снимать сон, где возможно.\nБойцы: игнорировать инферналов, всё на босса."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "Все: сразу выходи из «Смерти и разложения».\nТанк: держать центр, не двигаться при кольце льда.\nЛекари: быстро вылечить цель ледяной глыбы.\nБойцы: дальний бой широко рассредоточен (цепь ледяных стрел)."
