T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "Гильдия ещё не выдаёт очки добычи - твои значения появятся, когда руководство рейда запустит рейд."
T["The guild bank hasn't been read yet"] = "Банк гильдии ещё не прочитан"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "Руководство гильдии назначает лидеров и помощников рейда в разделе Корона > Модули > Рейды и добыча (по имени или с звания). В текущем рейде учитываются также лидер и помощники рейда."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "Руководство гильдии назначает лидеров рейда в разделе Корона > Модули > Рейды и добыча. В текущем рейде учитываются также лидер и помощники рейда."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "Руководство гильдии назначает лидеров рейда в разделе Корона > Модули > Рейды и добыча. В текущем рейде учитывается также лидер рейда."
T["The guild leadership only allows group searches from a higher rank."] = "Руководство гильдии разрешает поиск группы только с более высокого звания."
T["The guild leadership only allows polls from a higher rank."] = "Руководство гильдии разрешает опросы только с более высокого звания."
T["The guild leadership has disabled the partner search."] = "Руководство гильдии отключило поиск соратников."
T["The guild leadership has disabled open invites - challenge someone directly."] = "Руководство гильдии отключило открытые приглашения - вызови кого-нибудь напрямую."
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "Руководство гильдии задаёт в Корона > Модули, каким званиям это можно."
T["WoW's guild finder helps - neutral, no ads."] = "Поиск гильдий WoW поможет найти - нейтрально, без рекламы."
T["Only the guild master sets the limit. Rank 1 = guild master."] = "Предел задаёт только глава гильдии. Звание 1 = глава гильдии."
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "Кнопки вписывают команду в строку чата - она выполнится только по Enter."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "Сочетания есть и в назначении клавиш WoW: AddOns > Oasis. Esc закрывает окно Oasis (не в бою - там Esc принадлежит игре)."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "Сочетания есть и в назначении клавиш WoW: AddOns > Oasis. Esc закрывает окно Oasis, если ты последним щёлкнул в нём."
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "Панель уезжает вверх; подведи мышь к верхнему краю, и она опустится (только если закреплена вверху)"
T["The reservation line only appears while you are in a group or raid"] = "Строка резерва появляется только в группе или рейде"
T["The Scale of the Sands"] = "Стражи Песков"
