T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Кто отправляет данные, которые у других отклоняются (нет прав, поддельный автор, выдуманные записи). Неизменённый Oasis так практически не делает - это подсказка, не доказательство."
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "Кто заявит интерес, появится здесь на подходящем месте. Когда есть событие, записывайся прямо на карточке."
T["Who in the guild has the item on their wishlist"] = "У кого в гильдии этот предмет в списке желаний"
T["Who sees this section in the navigation (leadership always sees everything)"] = "Кто видит раздел в навигации (руководство видит всё всегда)"
T["Who left the guild or was removed. If someone returns, Oasis notifies guild management."] = "Кто покинул гильдию или был исключён. Если кто-то вернётся, Oasis сообщит руководству гильдии."
T["Who sees the crown at the top. Without rights it is grey and only opens a preview."] = "Кто видит корону вверху. Без прав она серая и открывает только превью."
T["Who may pin a message at the top of guild chat"] = "Кто может закреплять сообщение вверху чата гильдии"
T["Who can invite is not known yet - log in once with your main and Oasis will remember the guild leadership."] = "Кто может приглашать, пока неизвестно - зайди разок основным, и Oasis запомнит руководство гильдии."
T["Anyone up for %s? I'm looking for %s"] = "Кто со мной в %s? Ищу %s"
T["Who has ...?"] = "У кого есть ...?"
T["Who has the quest item you need? And whom can you help?"] = "У кого есть нужный тебе предмет задания? И кому можешь помочь ты?"
T["Who got what"] = "Кто что получил"
T["Who may book points (effort/loot) in raid."] = "Кто может начислять очки (ставки/добыча) в рейде."
T["Who in your group or raid has which buffs - and what's missing"] = "У кого в группе или рейде какие баффы - и чего не хватает"
T["Who is ready? Status lights per player"] = "Кто готов? Светофоры по игрокам"
T["Who is already saved this week, who is free and attuned – mains and alts"] = "Кто уже сохранён на этой неделе, кто свободен и с допуском - основные и твинки"
T["Who's online"] = "Кто в сети"
T["Who is online?"] = "Кто в сети?"
T["Who is online when"] = "Кто когда в сети"
T["Who is how far"] = "Кто как далеко"
T["Who crafts what, market, guild bank"] = "Кто что изготавливает, рынок, банк гильдии"
T["Who could join: %s"] = "Кто мог бы пойти: %s"
T["Who could join?"] = "Кто мог бы пойти?"
T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Кто часто участвует и мало получил, первым выбирает при «Нужно». Каждую неделю часть очков сгорает."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Кто запишется с подходящей ролью, сразу будет приглашён в твою группу."
T["Who stands where with which faction? Close to the goal, farm together, progress this week"] = "Кто где стоит у какой фракции? Почти у цели, фармить вместе, прогресс этой недели"
T["Who deals, heals and takes the most?"] = "Кто наносит больше всех, лечит больше всех, получает больше всех?"
T["The guild master decides who belongs to the leadership under Crown > Guild."] = "Кто входит в руководство, задаёт глава гильдии в Корона > Гильдия."
T["Stats"] = "Характеристики"
T["stats do nothing for your role"] = "характеристики бесполезны для твоей роли"
T["stats for info only"] = "характеристики только для справки"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Характеристики, альбом, цель на день, рекорды и приключения твоего персонажа."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Характеристики: +исцеление, интеллект, дух, восст. маны;Оружие: посох или одноручное + левая рука с исцелением;Лечение: Омоложение и Восстановление заранее, Целительное прикосновение для сильных ударов;Совет: Озарение для маны, Возрождение для павших лекарей"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Характеристики: +исцеление, интеллект, крит заклинаний (Просветление возвращает ману), восст. маны;Оружие: одноручное + левая рука/щит с исцелением;Лечение: Вспышка Света для малого урона, Свет небес (низкий ранг) для сильных ударов;Совет: раздавай благословения, Божественная защита, если на тебя агро"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Характеристики: +исцеление, восст. маны (MP5), интеллект - дух даёт мало;Оружие: одноручное + щит с исцелением;Лечение: Цепное исцеление для групп, Волна исцеления (низкий ранг) для танка;Совет: ставь Тотем источника маны, Щит земли на танка"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Характеристики: +исцеление, дух (Медитация: восстановление и при чтении), интеллект, восст. маны;Оружие: посох или одноручное + левая рука с исцелением, жезл;Лечение: Обновление и Слово силы: Щит заранее, Великое исцеление (низкий ранг) для танка;Совет: Молитва исцеления для группы, Уход в тень при агро"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Характеристики: броня (облик медведя её умножает), выносливость, ловкость (уклонение + броня);Оружие: урон неважен - важны только характеристики (посох/древковое с выносливостью);Ротация: Трёпка, Размах для групп, Деморализующий рёв;Совет: сила для угрозы, Исступление на старте"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Характеристики: сила (1 очко = 2 СА), ловкость (СА + крит), крит, меткость до +9 %;Оружие: урон неважен - важны только характеристики;Ротация: Цапнуть/Полоснуть для приёмов серии, затем Свирепый укус;Совет: смена облика ради энергии, нападение из незаметности"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Характеристики: сила (1 очко = 2 СА), крит (вызывает Шквал = быстрее удары), меткость до +9 %;Оружие: медленное двуручное - Неистовство ветра срабатывает за удар, чем медленнее, тем больше урона;Ротация: Оружие неистовства ветра, Удар бури, Земной шок;Совет: Тотем силы земли и Тотем неистовства ветра для группы"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Характеристики: сила (1 очко = 2 СА), крит, меткость до +9 %;Оружие: медленное двуручное - печати и Правосудие действуют за удар;Ротация: Печать праведности/повеления, Правосудие, обновить печать;Совет: Освящение только при достатке маны, Благословение могущества на себя"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Характеристики: меткость до +9 %, ловкость (1 СА, ок. 29 = 1 % крита), СА, крит;Оружие: Бой = быстрое в левой, медленное в правой (Коварный удар); кинжалы для Удара в спину;Ротация: копить приёмы серии, держать Мясорубку, затем Потрошение;Совет: с двумя оружиями белые удары чаще промахиваются - меткость важнее всего"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Характеристики: меткость до +9 %, ловкость (2 СА дальн. боя, ок. 53 = 1 % крита), СА, интеллект;Оружие: медленное оружие дальнего боя (большой урон за выстрел), оружие ближнего боя ради характеристик;Ротация: Метка охотника, Автоматическая стрельба, Прицельный/Залп между ними;Совет: корми питомца и держи его довольным, Замораживающая ловушка (квадрат) для контроля"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Характеристики: меткость до +9 %, сила (1 очко = 2 СА), крит (ок. 20 ловкости = 1 %);Оружие: медленное двуручное (Смертельный удар, Удар героя действуют за удар);Ротация: копить ярость, Смертельный удар / Кровожадность, Вихрь, лишняя ярость в Удар героя;Совет: Боевой крик перед пуллом, Казнь ниже 20 % здоровья"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Характеристики: защита (440 = на 60 ур. иммунитет к критам боссов), выносливость, броня, блок;Оружие: одноручное + щит, быстрое оружие = больше ярости;Ротация: Мощный удар щитом/Реванш, Раскол брони на цель, Удар героя при избытке ярости;Совет: меткость помогает, чтобы Провокация и умения не промахивались"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Характеристики: защита, выносливость, броня, затем урон от заклинаний ради угрозы;Оружие: одноручное (лучше с уроном от заклинаний) + щит;Ротация: Праведное неистовство вкл., Освящение для групп, держать Щит небес;Совет: маны мало - бери Печать мудрости или немного интеллекта"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Характеристики: урон от заклинаний, крит заклинаний (Сосредоточенность стихий экономит ману), интеллект, восст. маны;Оружие: одноручное + щит/левая рука с уроном от заклинаний;Ротация: спамить Молнию, Цепная молния по группам, Огненный шок;Совет: меткость заклинаний до +16 % в рейде, Тотем источника маны против нехватки маны"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Характеристики: урон от заклинаний, крит заклинаний, интеллект, меткость заклинаний до +16 % в рейде;Оружие: посох или одноручное + левая рука с уроном от заклинаний;Ротация: Лунный огонь + Рой насекомых, затем Гнев или Звёздный огонь;Совет: Озарение на себя, когда маны мало"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Характеристики: урон от заклинаний, меткость заклинаний до +16 % (рейд), выносливость, интеллект;Оружие: посох или кинжал + левая рука с уроном от заклинаний, жезл для остатков маны;Ротация: Порча + проклятие, затем Стрела Тьмы; Жизнеотвод вместо питья;Совет: выносливость окупается вдвойне (Жизнеотвод, Демон Бездны/Связка душ)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Характеристики: урон от заклинаний, меткость заклинаний до +16 % (рейд), дух для маны;Оружие: посох или одноручное + левая рука с уроном от заклинаний;Ротация: Слово Тьмы: Боль, Взрыв разума, Пытка разума;Совет: постоянно в Облике Тьмы, Объятия вампира лечат группу"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Характеристики: урон от заклинаний, затем меткость заклинаний до +16 % (рейдовые боссы), интеллект, крит заклинаний;Оружие: посох с уроном от заклинаний плюс жезл для остатков маны;Ротация: спамить Ледяную стрелу или Огненный шар, Прилив сил без маны;Прокачка: интеллект и дух = меньше пауз, в группах ставь овцу (луна)"
