T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Оставь журнал боя включённым (Настройки > Разделы > Рейтинг боёв, включено по умолчанию).\n2.  После игры дважды щёлкни ImportCrits.bat в папке Oasis.\n3.  В игре /reload - твой лучший крит появится здесь и будет виден гильдии."
