T["Active: meme sounds, music and guild emojis are included."] = "Активно: мем-звуки, музыка и эмодзи гильдии включены."
T["Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."] = "Активные участники ниже офицерских рангов попадают в список «Повышение» после стольких дней в одном ранге. 0 = выкл."
T["Current zone first"] = "Сначала текущая зона"
T["All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."] = "Все разделы по темам: гильдия, совместная игра, рейд, торговля, развлечения. Клик по заголовку сворачивает группу."
T["Expand all zones"] = "Развернуть все зоны"
T["Collapse all zones"] = "Свернуть все зоны"
T["All members with rank, level and Oasis version. Right-click a row: change rank."] = "Все участники с рангом, уровнем и версией Oasis. ПКМ по строке: сменить ранг."
T["All fonts under the SIL Open Font License 1.1"] = "Все шрифты под лицензией SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Жгучий адреналин: СРАЗУ выбегай из рейда (ты сейчас умрёшь).\nAll: Полные ресурсы в начале - используй всё.\nTank: Назначить порядок танков (Адреналин на танке).\nDD: Не стоять перед драконом и за ним."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Не давайте 8 Firesworn умирать рядом с рейдом (взрыв).\nTank: Каждый танк аддов уводит своего Firesworn, чернокнижники изгоняют.\nHealer: Рассеивать, следить за танками аддов.\nDD: Сначала Гарр, адды только по команде."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Двух Core Rager танковать в стороне от босса, не убивать.\nTank: Менять танка Големагга, когда Magma Splash стакается слишком высоко.\nDD: Только Големагг."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Сначала 4 жреца, они лечат друг друга.\nTank: Держать Сульфурона и жрецов раздельно.\nDD: Прерывать! Сбивать Dark Mending жрецов."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: Защита от огня! Гнев Рагнароса отбрасывает ближний бой - потом снова к боссу.\nAll: Фаза сыновей (через 3 мин или при погружении): убить всех Сыновей пламени.\nTank: Второй танк наготове, когда первого отбросит.\nHealer: Рассредоточиться, дальний бой не слишком близко (Lava Burst).\nDD: Ближний бой: следить за маной, дальний бой - на дистанции."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet стакается - дальний бой за колонны, чтобы спал.\nTank: Два танка за колоннами, Wing Buffet отбрасывает.\nDD: Плащ из чешуи Ониксии обязателен."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Проклятие Гееннаса (меньше лечения) снимать сразу.\nAll: Выйти из Огненного ливня.\nTank: Двух Flamewaker танковать раздельно.\nDD: Сначала Flamewaker, потом Гееннас."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Проклятие Люцифрона и Impending Doom снимать сразу (маги/друиды, жрецы/паладины).\nTank: Двух стражей танковать раздельно - контроль над разумом!\nHealer: Рассредоточиться, рассеивать подконтрольных игроков.\nDD: Сначала стражи, потом Люцифрон."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Живая бомба: СРАЗУ выбегай из рейда!\nAll: Инферно - от босса, рассеивать Ignite Mana.\nTank: Держать центр, на Инферно ненадолго выйти.\nDD: Ближний бой на Инферно отходит."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Следить за отражением магии/щитом урона стражей - тогда стоп урон.\nTank: По стражу на танка, маги превращают элитных стражей в овец.\nDD: Сначала стражи-лекари (Flamewaker Healer)."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Никогда не стоять перед Ониксией и за ней (дыхание и удар хвостом).\nAll: Фаза 2 (65%): уворачиваться от огненных шаров, не заходить во входы пещер.\nAll: Фаза 3 (40%): страх - Защита от страха/Тотем трепета наготове, избегать трещин с лавой.\nTank: Ониксия боком у стены, головой от рейда.\nTank: Фаза 2: собрать дракончиков. Фаза 3: сразу вернуть агро.\nHealer: Танк в приоритете, в фазе 2 рассредоточиться.\nDD: Подождать 3 атаки танка. Фаза 2: сначала дракончики."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Паника - Защита от страха/Тотем трепета, охотники: Усмиряющий выстрел на Бешенство.\nAll: Выйти из огня на полу.\nTank: Магмадар спиной к рейду.\nDD: Дальний бой рассредоточен сзади."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Фаза 1: драконоры с обеих сторон, следить за классовыми призывами.\nAll: Фаза 3 (20%): скелеты встают снова - убить ещё раз.\nTank: Нефариан у стены, страх - Защита от страха.\nHealer: Призыв для жрецов: лечение наносит урон - осторожно.\nDD: Охотники/воины: следить за призывами (оружие пропадает, стойка)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Фаза 1: уничтожать яйца (контроль над разумом через сферу), перехватывать аддов.\nAll: После всех яиц: босс в комнате - Fire Nova.\nTank: Собирать аддов у лестниц.\nDD: Сначала маги и драконоры."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Бешенство - охотники: Усмиряющий выстрел.\nTank: Два танка, следить за Wing Buffet.\nDD: Плащ из чешуи Ониксии обязателен."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Shadow of Ebonroc лечит босса - танк с дебаффом меняется.\nTank: Два танка меняются на Shadow.\nDD: Плащ из чешуи Ониксии обязателен."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Отбрасывание - встать к стене.\nTank: Два танка, агро делится из-за Knock Away.\nDD: Смертельный удар по танку: лекарям быть готовыми."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Он телепортируется - у кого агро, не убегать.\nAll: Снимать Проклятие Шаззраха, Чародейский взрыв: ближний бой на дистанции.\nTank: После каждого скачка сразу обратно к нему.\nHealer: Рассеивать (Deaden Magic)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Два из пяти видов дыхания в неделю - от дыхания прятаться за углом.\nAll: Hourglass Sand от бронзового недуга.\nTank: Танковать у ворот, рейд за углом.\nDD: На Бешенство - Усмиряющий выстрел."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Удерживай Alt: все характеристики и оценка. Shift: сравнение Blizzard."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Отпусти Alt: компактный вид. Shift: сравнение Blizzard."
