T["Dock to the talent window again"] = "Снова прикрепить к окну талантов"
T["In a group WoW does not tell addons who landed a hit. Oasis only counts a critical hit if it directly follows your own attack and matches the damage meter after the fight. Marked as estimated in the ranking."] = "В группе WoW не сообщает аддонам, кто нанёс удар. Oasis считает крит, только если он идёт сразу за твоей атакой и после боя совпадает со счётчиком урона. В рейтинге помечен как оценочный."
T["WoW classics"] = "Классика WoW"
T["Weekly tasks %d/%d"] = "Недельные задания %d/%d"
T["World of Warcraft and related names, crests and artwork are trademarks of Blizzard Entertainment. Oasis is a fan project and is not affiliated with Blizzard."] = "World of Warcraft и связанные названия, гербы и графика - товарные знаки Blizzard Entertainment. Oasis - фанатский проект и не связан с Blizzard."
T["Rolling: order need > off-spec > transmog, then the roll. Points: priority from loot points decides. Loot council: officers vote, the master looter awards."] = "Броски: порядок нужда > доп. специализация > трансмог, затем бросок. Очки: решает приоритет по очкам добычи. Совет по добыче: офицеры голосуют, ответственный за добычу выдаёт."
T["Gear = settings (look, sounds, notifications). Next to it the language and - for guild leadership - the crown."] = "Шестерёнка = настройки (вид, звуки, уведомления). Рядом язык и - для руководства гильдии - корона."
T["Shows which materials green, blue and epic items can disenchant into"] = "Показывает, какие материалы можно получить при распылении зелёных, синих и эпических предметов"
T["Shows in the listing that you talk by voice (Discord etc.). Joining is still handled by Blizzard / your group leader."] = "Показывает в поиске, что вы общаетесь голосом (Discord и т.п.). Вступлением по-прежнему управляет Blizzard / лидер группы."
T["Shows mains only. Alts are characters assigned to another main."] = "Показывает только основных. Твинки - персонажи, привязанные к другому основному."
T["Shows only the header with the number of builds."] = "Показывает только заголовок с числом билдов."
T["Shows at a glance who in the guild has the same quests and is online right now - one click invites them."] = "Сразу показывает, у кого в гильдии те же задания и кто сейчас в сети - один клик приглашает."
